import numpy as np, mujoco, rcb_dtb
from scipy.spatial.transform import Rotation as Rot
class Controller:
 def __init__(self,s):
  self.s=s; self.m=s.model; self.d=s.data; self.k=mujoco.MjData(self.m)
  self.bid=self.m.body('palmleft_hand_C_MC').id
  self.arm=s._jq[:7]; self.av=s._jv[:7]; self.jp=np.zeros((3,self.m.nv)); self.jr=self.jp.copy()
 def pose(self):return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,p,R,q=None):
  if q is None:q=self.d.qpos[self.s._jq].copy()
  self.k.qpos[:]=self.d.qpos; self.k.qpos[self.s._jq]=q
  for it in range(100):
   mujoco.mj_kinematics(self.m,self.k);mujoco.mj_comPos(self.m,self.k)
   cp=self.k.xpos[self.bid];cr=self.k.xmat[self.bid].reshape(3,3)
   e=np.r_[p-cp,Rot.from_matrix(R@cr.T).as_rotvec()]
   if np.linalg.norm(e[:3])<1e-5 and np.linalg.norm(e[3:])<1e-4:break
   mujoco.mj_jacBody(self.m,self.k,self.jp,self.jr,self.bid)
   J=np.vstack([self.jp[:,self.av],self.jr[:,self.av]])
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   dq=np.clip(dq,-.15,.15)
   self.k.qpos[self.arm]=np.clip(self.k.qpos[self.arm]+dq,self.s.lower[:7]+.001,self.s.upper[:7]-.001)
  return self.k.qpos[self.s._jq].copy()
 def move(self,p,R,hand=None,n=120):
  p0,R0=self.pose();q=self.d.qpos[self.s._jq].copy()
  for i in range(n):
   t=(i+1)/n;t=t*t*(3-2*t)
   Ri=Rot.from_rotvec(t*Rot.from_matrix(R@R0.T).as_rotvec()).as_matrix()@R0
   q=self.ik(p0+t*(p-p0),Ri,q)
   if hand is not None:q[7:]=hand
   pr=self.s.step(q)
  return pr
 def hold(self,n=120):
  for _ in range(n):pr=self.s.step(self.s.targets)
  return pr
 def dump(self,path):
  from PIL import Image
  Image.fromarray(self.s.render_grid(size=(640,480))).save(path)
 def contacts(self):
  cs=[]
  for ct in self.d.contact:
   if self.m.geom_bodyid[ct.geom1]==self.s._obj or self.m.geom_bodyid[ct.geom2]==self.s._obj:
    f=np.zeros(6);mujoco.mj_contactForce(self.m,self.d,len(cs),f)
    cs.append((self.m.geom(ct.geom1).name,self.m.geom(ct.geom2).name,ct.dist))
  return cs
if __name__=='__main__':
 s=rcb_dtb.Session();c=Controller(s);p,R=c.pose();print('H pose',p,R)
 for v in [0,.4,.8,1.2,1.5]:
  q=rcb_dtb.INIT_Q.copy();q[7:12]=[1.3,0,.5,0,.7]
  for j in [12,16,20,25]:q[j:j+4]=[v,0,1.2,.5]
  c.k.qpos[:]=c.d.qpos;c.k.qpos[s._jq]=q;mujoco.mj_forward(c.m,c.k)
  print('candidate',v)
  for f in ['thumb','index','middle','ring','pinky']:
   b=c.m.body('palmleft_'+f+'_DP').id
   gid=c.m.geom('palmleft_'+f+'_elastomer').id
   print(f,'tipH',R.T@(c.k.geom_xpos[gid]-p),'tipW',c.k.geom_xpos[gid])
